	dir := t.TempDir()
	opts := log.Options{SegmentBytes: 1 << 20}
	l := open(t, dir, opts)
	commit(t, l, []byte("one")) // seq 1
	l.Close()

	// Tear seq 2 into a permanent hole; reopen and commit seq 3.
	appendTornEntry(t, dir, 2)
	l = open(t, dir, opts)
	b3, err := l.Append([][]byte{[]byte("three")})
